namespace PriceCalculatorDemo;

public class PriceCalculator
{
    public decimal CalculateTotal(decimal unitPrice, int quantity)
    {
        ArgumentOutOfRangeException.ThrowIfNegative(unitPrice);
        ArgumentOutOfRangeException.ThrowIfNegativeOrZero(quantity);
        return unitPrice * quantity;
    }

    public decimal ApplyDiscount(decimal total, decimal discountPercent)
    {
        ArgumentOutOfRangeException.ThrowIfNegative(total);
        ArgumentOutOfRangeException.ThrowIfNegative(discountPercent);
        ArgumentOutOfRangeException.ThrowIfGreaterThan(discountPercent, 100m);
        return total * (1 - discountPercent / 100m);
    }
}

using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace PriceCalculatorDemo.Tests;

[TestClass]
public class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // ─── DataRow: inline constant values ───────────────────────────────

    [TestMethod]
    [DataRow(10.00, 1, 10.00)]
    [DataRow(10.00, 5, 50.00)]
    [DataRow(0.99, 3, 2.97)]
    [DataRow(0.00, 1, 0.00)]
    [DataRow(100.50, 10, 1005.00)]
    public void CalculateTotal_ReturnsExpectedResult(
        double unitPrice, int quantity, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity);
        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    [DataRow(100.00, 0.0, 100.00)]
    [DataRow(100.00, 10.0, 90.00)]
    [DataRow(100.00, 50.0, 50.00)]
    [DataRow(100.00, 100.0, 0.00)]
    [DataRow(49.99, 25.0, 37.4925)]
    public void ApplyDiscount_ReturnsExpectedResult(
        double total, double discountPercent, double expected)
    {
        var result = _calculator.ApplyDiscount((decimal)total, (decimal)discountPercent);
        Assert.AreEqual((decimal)expected, result);
    }

    // ─── DynamicData: complex or computed test cases ───────────────────

    public static IEnumerable<object[]> CalculateTotalEdgeCases =>
    [
        [0.01m, 1, 0.01m],
        [decimal.MaxValue / 2, 1, decimal.MaxValue / 2],
        [9999.99m, 100, 999_999.00m],
    ];

    [TestMethod]
    [DynamicData(nameof(CalculateTotalEdgeCases))]
    public void CalculateTotal_EdgeCases_ReturnsExpectedResult(
        decimal unitPrice, int quantity, decimal expected)
    {
        var result = _calculator.CalculateTotal(unitPrice, quantity);
        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<object[]> InvalidDiscountCases
    {
        get
        {
            yield return [100m, -1m, typeof(ArgumentOutOfRangeException)];
            yield return [100m, 101m, typeof(ArgumentOutOfRangeException)];
            yield return [-1m, 10m, typeof(ArgumentOutOfRangeException)];
        }
    }

    [TestMethod]
    [DynamicData(nameof(InvalidDiscountCases))]
    public void ApplyDiscount_InvalidInputs_Throws(
        decimal total, decimal discountPercent, Type expectedExceptionType)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(total, discountPercent));
    }

    // ─── DynamicData from a method (useful for external/shared data) ──

    public static IEnumerable<object[]> GetBulkDiscountScenarios()
    {
        // Simulates loading scenarios that might come from config or shared logic
        yield return [500.00m, 5.0m, 475.00m];
        yield return [1000.00m, 15.0m, 850.00m];
        yield return [2500.00m, 20.0m, 2000.00m];
    }

    [TestMethod]
    [DynamicData(nameof(GetBulkDiscountScenarios), DynamicDataSourceType.Method)]
    public void ApplyDiscount_BulkScenarios_ReturnsExpectedResult(
        decimal total, decimal discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(total, discountPercent);
        Assert.AreEqual(expected, result);
    }

    // ─── CalculateTotal invalid inputs ────────────────────────────────

    [TestMethod]
    [DataRow(-1.00, 1)]
    public void CalculateTotal_NegativePrice_Throws(double unitPrice, int quantity)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity));
    }

    [TestMethod]
    [DataRow(10.00, 0)]
    [DataRow(10.00, -1)]
    public void CalculateTotal_InvalidQuantity_Throws(double unitPrice, int quantity)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity));
    }
}

