+        [9999.99m, 100, 999_999.00m],
+    ];
+
+    [TestMethod]
+    [DynamicData(nameof(CalculateTotalEdgeCases))]
+    public void CalculateTotal_EdgeCases_ReturnsExpectedResult(
+        decimal unitPrice, int quantity, decimal expected)
+    {
+        var result = _calculator.CalculateTotal(unitPrice, quantity);
+        Assert.AreEqual(expected, result);
+    }
+
